manifest = []
for slug, title, tagline, sky, horizon, moon, scenery in scenes:
    svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="900" viewBox="0 0 1600 900" role="img" aria-label="{title} loading illustration">
<defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="{sky}"/><stop offset="1" stop-color="{horizon}"/></linearGradient><linearGradient id="shade" x2="0" y2="1"><stop stop-color="#161824" stop-opacity="0"/><stop offset="1" stop-color="#161824" stop-opacity=".86"/></linearGradient></defs>
<path fill="url(#sky)" d="M0 0h1600v900H0z"/><circle cx="1250" cy="190" r="112" fill="{moon}" opacity=".83"/>{scenery}<path fill="url(#shade)" d="M0 590h1600v310H0z"/>
<path d="M105 755h90" stroke="{moon}" stroke-width="5"/><text x="105" y="815" fill="#fff2dc" font-family="Georgia,serif" font-weight="bold" font-size="52" letter-spacing="3">{title}</text><text x="108" y="855" fill="#f0d9bd" font-family="Arial,sans-serif" font-size="16" letter-spacing="4">{tagline}</text></svg>'''
    (OUT / f'{slug}.svg').write_text(svg, encoding='utf-8')
    manifest.append({'id':slug,'file':f'loading/{slug}.svg','width':1600,'height':900,'title':title})
(ROOT / 'loading.json').write_text(json.dumps(manifest, indent=2)+'\n', encoding='utf-8')
print(f'generated {len(manifest)} loading illustrations')
